-- =====================================================================
-- The hunters' sheets as they stood in their PDFs. Run once, after
-- setup.sql. Generated from assets/sheets/data/*.json.
-- Running it again resets every sheet to these values (XP awards and
-- purchases are kept, but approved purchases vanish from the sheets).
-- =====================================================================
insert into public.character_sheets (slug, chronicle, name, data, play) values
  ('payne', 'dead-hand', 'Remington Ian Payne',
   $sheet${"name": "Remington Ian Payne", "concept": "", "creed": "Martial", "cell": "Dead Hand  -  S.A.B.E.R", "drive": "Guilt", "redemption": "", "attributes": {"strength": 3, "dexterity": 2, "stamina": 3, "charisma": 2, "manipulation": 1, "composure": 2, "intelligence": 4, "wits": 2, "resolve": 3}, "skills": {"athletics": 1, "brawl": 1, "craft": 3, "drive": 0, "firearms": 3, "larceny": 1, "melee": 0, "stealth": 2, "survival": 3, "animalken": 0, "etiquette": 0, "insight": 0, "intimidation": 2, "leadership": 2, "performance": 0, "persuasion": 1, "streetwise": 1, "subterfuge": 0, "academics": 0, "awareness": 2, "finance": 0, "investigation": 1, "medicine": 2, "occult": 0, "politics": 0, "science": 0, "technology": 1}, "specialties": [{"skill": "craft", "name": "Makeshift explosive devices and propulsion devices"}, {"skill": "firearms", "name": "Long Rifle Accuracy"}, {"skill": "survival", "name": "Camouflage"}], "edges": [{"name": "ARSENAL (Asset)", "perks": ["Expand access to bigger guns"], "notes": "Weapons beyond civilian reach: firearms, melee, kit"}, {"name": "ORDNANCE (Asset)", "perks": [], "notes": "Explosives, breaching charges, demolition tools"}], "advantages": [{"name": "Safe House", "dots": 3}, {"name": "Allies", "dots": 3}, {"name": "Resources", "dots": 1}, {"name": "Nightmares (Flaw)", "dots": 1}, {"name": "[Reversed] Enemy in the Institution (Flaw)", "dots": 1}], "tenets": "", "creedFields": "ANCHOR\nDont Trust Anybody"}$sheet$::jsonb,
   $sheet${"ambition": "Erradicate the supernatural for OUR planet.", "desire": "Routine post-retirement.", "health": ["", "", "", "", "", "", "", "", "", ""], "willpower": ["", "", "", "", "", "", "", "", "", ""], "despair": false, "touchstones": "DAUGHTER\nWas a twin; one of the twins was\nkilled by a supernatural being.\n\nEX  -  MOTHER OF THE DAUGHTER", "equipment": ["", "", "", "", "", "", "", "", "", "", "", "", "", ""], "notes": "Player: Sheeno\nHumanity 7 - Health 6 - Willpower 5\nDesperation and Danger are tracked per cell,\nnot per character.", "age": "", "dob": "", "appearance": "", "features": "", "history": ""}$sheet$::jsonb),
  ('dorian', 'dead-hand', 'Dorian DeLisle',
   $sheet${"name": "Dorian DeLisle", "concept": "Darkweb dealer’s remorse", "creed": "Underground", "cell": "Dead Hand", "drive": "Atonement", "redemption": "The cell must protect someone from the quarry", "attributes": {"strength": 2, "dexterity": 3, "stamina": 2, "charisma": 2, "manipulation": 2, "composure": 1, "intelligence": 3, "wits": 4, "resolve": 3}, "skills": {"athletics": 1, "brawl": 1, "craft": 0, "drive": 0, "firearms": 2, "larceny": 1, "melee": 2, "stealth": 2, "survival": 1, "animalken": 0, "etiquette": 1, "insight": 0, "intimidation": 0, "leadership": 0, "performance": 0, "persuasion": 0, "streetwise": 2, "subterfuge": 2, "academics": 0, "awareness": 3, "finance": 0, "investigation": 1, "medicine": 1, "occult": 3, "politics": 0, "science": 0, "technology": 3}, "specialties": [{"skill": "occult", "name": "Necromancy"}, {"skill": "technology", "name": "Surveillance Systems"}], "edges": [{"name": "GLOBAL ACCESS (Int + Technology)", "perks": ["All Access Pass", "Big Brother"], "notes": ""}, {"name": "ARTEFACT  -  Fetish of Lwa (Int + Occult)", "perks": ["Shield"], "notes": "(+1 Stealth) - Sense the Unnatural"}], "advantages": [{"name": "Mask", "dots": 2}, {"name": "Resources", "dots": 1}, {"name": "Safe House", "dots": 2}, {"name": "Status  -  respected", "dots": 2}, {"name": "Adversary (Flaw)", "dots": 1}, {"name": "Creepy Safe House (Flaw)", "dots": 1}], "tenets": "", "creedFields": "CREED FIELD\nStealth and Subterfuge"}$sheet$::jsonb,
   $sheet${"ambition": "", "desire": "", "health": ["", "", "", "", "", "", "", "", "", ""], "willpower": ["", "", "", "", "", "", "", "", "", ""], "despair": false, "touchstones": "MERCEDES\nDante’s daughter, also living in\nNYC", "equipment": ["Hacking laptop", "Earbuds", "Glock (+2 damage)", "", "", "", "", "", "", "", "", "", "", ""], "notes": "Player: Andreas\nChronicle: Dead Hand", "age": "48", "dob": "1984, September", "appearance": "A black man, from the south. Rugged look, wearing lots of accessories like pendants, rings, wristbands; a few faded tattoos on arms and chest. Dreadlocks usually tied in a ponytail, beard unkempt.", "features": "Lots of pendants and charms of Haitian origin; one specific charm in the form of an old voodoo doll hangs on his belt.", "history": "A divorced hipster man of Louisiana, touched by Haitian voodoo, but found passion in cybersecurity. A known figure among smugglers and shady operatives. One leg in the cyberworld, yet hesitant to let go of his late mother’s faith. His house is decorated with various trinkets and decorations he managed to obtain."}$sheet$::jsonb),
  ('jack', 'dead-hand', 'Jack Zeppelin',
   $sheet${"name": "Jack Zeppelin", "concept": "Envious College Football Talent", "creed": "Martial", "cell": "Dead Hand", "drive": "Envy", "redemption": "", "attributes": {"strength": 4, "dexterity": 3, "stamina": 2, "charisma": 3, "manipulation": 1, "composure": 3, "intelligence": 2, "wits": 2, "resolve": 2}, "skills": {"athletics": 3, "brawl": 3, "craft": 0, "drive": 0, "firearms": 0, "larceny": 0, "melee": 0, "stealth": 3, "survival": 2, "animalken": 0, "etiquette": 0, "insight": 2, "intimidation": 3, "leadership": 1, "performance": 0, "persuasion": 0, "streetwise": 0, "subterfuge": 0, "academics": 1, "awareness": 2, "finance": 0, "investigation": 0, "medicine": 0, "occult": 0, "politics": 0, "science": 0, "technology": 1}, "specialties": [{"skill": "athletics", "name": "Football"}, {"skill": "academics", "name": "First Nation History"}], "edges": [{"name": "ARTIFACT (Endowment)", "perks": ["add 1 die twice, or 2 dice once, to Str or Dex"], "notes": "A strange object carrying a genuine supernatural effect"}, {"name": "REPEL THE UNNATURAL (Endowment)", "perks": [], "notes": "Ward off or drive back a supernatural creature"}], "advantages": [{"name": "Mentor  -  Mathew, his coach", "dots": 2}, {"name": "Fast Reflexes", "dots": 3}, {"name": "Iron Will", "dots": 2}, {"name": "Nightmares (Flaw)", "dots": 1}, {"name": "Overconfident (Flaw)", "dots": 1}, {"name": "Infamy (Flaw)", "dots": 1}], "tenets": "", "creedFields": "ANCHOR\nI believe that everyone can be\nredeemed with the right help."}$sheet$::jsonb,
   $sheet${"ambition": "Become a professional NFL player", "desire": "Find his missing grandma, and return her to his father to make him proud", "health": ["", "", "", "", "", "", "", "", "", ""], "willpower": ["", "", "", "", "", "", "", "", "", ""], "despair": false, "touchstones": "MATTHEW\nHis coach and father figure, looked\nup to and cherished.\n\nJAMES ZEPPELIN (little brother)\nKeeps him grounded and lets him\nremember his roots.\n\nMARRIONET ZEPPELIN\nJack’s mother; she is a housewife.", "equipment": ["", "", "", "", "", "", "", "", "", "", "", "", "", ""], "notes": "Player: Youssef\nHumanity 7 - Health 5 - Willpower 5\nDesperation and Danger are tracked per cell,\nnot per character.", "age": "", "dob": "", "appearance": "A tall 6’3 white college student. Short scruffy hair, always in oversized hoodies. Wears a gifted bracelet on one wrist and a watch on the other. Scar on his shoulder from surgery. Growing a beard.", "features": "", "history": "Mentor: Mathew, his coach, whom Jack sees as a father figure. Matthew comes from a line of Hunters, however he chose to become an athlete over the family tradition. He has now retired and helps the Tradition by recruiting and training new talent.\n\nFast Reflexes: after many years of continuous practice he knows how to focus, and is able to gather his focus to have fast reflexes.\n\nIron Will: due to how people underestimate him, and people thinking that he doesn’t deserve his spot, he is almost always dead set on proving to himself that he is worth being here.\n\nOverconfident: people his whole life have been complimenting him and giving him confidence, not knowing his own limits.\n\nInfamy: his father is the president of the football association, so people think he doesn’t deserve his status.\n\nNightmares: for the last year, he has not been able to get a good night’s rest."}$sheet$::jsonb),
  ('ezekiel', 'dead-hand', 'Ezekiel Delacroix',
   $sheet${"name": "Ezekiel Delacroix", "concept": "The ex-cop New Orleans forgot to stop", "creed": "Inquisitive", "cell": "Dead Hand", "drive": "Oath", "redemption": "", "attributes": {"strength": 2, "dexterity": 2, "stamina": 2, "charisma": 3, "manipulation": 1, "composure": 2, "intelligence": 4, "wits": 3, "resolve": 3}, "skills": {"athletics": 1, "brawl": 0, "craft": 0, "drive": 0, "firearms": 1, "larceny": 0, "melee": 0, "stealth": 1, "survival": 1, "animalken": 1, "etiquette": 0, "insight": 2, "intimidation": 1, "leadership": 0, "performance": 0, "persuasion": 0, "streetwise": 2, "subterfuge": 1, "academics": 0, "awareness": 2, "finance": 0, "investigation": 3, "medicine": 0, "occult": 2, "politics": 0, "science": 2, "technology": 2}, "specialties": [{"skill": "investigation", "name": "Cold Cases"}, {"skill": "streetwise", "name": "Informants"}, {"skill": "occult", "name": "Louisiana Folklore"}], "edges": [{"name": "GLOBAL ACCESS (Aptitude)", "perks": ["call in a favour beyond his own reach"], "notes": "Hacking, surveillance, data access most cannot touch"}, {"name": "LIBRARY (Asset)", "perks": [], "notes": "Archives, contacts, a database on the supernatural"}], "advantages": [{"name": "Contacts", "dots": 3}, {"name": "Iron Will", "dots": 2}, {"name": "Status", "dots": 2}, {"name": "Addiction (Flaw)", "dots": 2}], "tenets": "", "creedFields": "CONCEPT\nStill dragging a corkboard and a\ndead K9 handler’s dog through\ncases the department wants buried\n-  and he’s rarely wrong about\nwhat’s underneath."}$sheet$::jsonb,
   $sheet${"ambition": "Find the name behind the case that ended his career  -  the one that isn’t supposed to exist on paper  -  and finally make it stick to something real.", "desire": "Close this case clean, for once, without anyone else paying for what he didn’t catch in time.", "health": ["", "", "", "", "", "", "", "", "", ""], "willpower": ["", "", "", "", "", "", "", "", "", ""], "despair": false, "touchstones": "PRYIA CHEN\nThe hacker friend, known for years. One of maybe two\npeople he trusts without reservation. She has stopped\nasking follow-up questions, which worries him more than\nif she pushed.\n\nBISHOP\nNot a warm dog. Trained, controlled, present. Since\nRosa’s death he alerts on things in no K9 manual  -  a\nflat, dead stillness aimed at a person or a room. He is\nnever wrong.\n\nDARA SILVA\nRosa’s younger sister. The official story never sat\nright with her either. Ezekiel checks in on her more\nthan he would admit.", "equipment": ["", "", "", "", "", "", "", "", "", "", "", "", "", ""], "notes": "Player: Ibra\nHumanity 7 - Health 5 - Willpower 5\nDesperation and Danger are tracked per cell,\nnot per character.\n\nTONE\nWorn-down conviction, gallows humour; a man\nwho ran out of capacity for surprise a long\ntime ago and kept working anyway.", "age": "", "dob": "", "appearance": "", "features": "", "history": "Fourteen years on the force, mostly homicide, and Ezekiel was good at it  -  not flashy, just relentless. He didn’t let go of threads other detectives filed and forgot. That is what got him: a string of deaths written up as unrelated  -  overdoses, accidents, one ruled suicide he still doesn’t believe. He pulled the thread anyway and found all of them connected to a name that kept not existing on paper. His captain told him to drop it. He didn’t. Six months later he was out. Official story: conduct unbecoming. Unofficial story: somebody above his pay grade didn’t want the questions asked.\n\nHe has run his own PI shop since, taking the cases nobody else wants  -  missing persons that don’t add up, deaths closed too fast, families who know something is wrong and can’t get anyone in a uniform to listen. He has a corkboard that would make a task force uncomfortable, red string included, and he is right often enough that it has stopped being funny.\n\nHe smokes constantly. Not really for the nicotine  -  for the ritual. Lighting up is punctuation: the two seconds he allows himself between finding out something terrible and having to do something about it."}$sheet$::jsonb),
  ('adelina', 'dead-hand', 'Adelina Morte',
   $sheet${"name": "Adelina Morte", "concept": "Vengeful ex-spy", "creed": "Underground", "cell": "Dead Hand", "drive": "Rage", "redemption": "", "attributes": {"strength": 1, "dexterity": 3, "stamina": 2, "charisma": 2, "manipulation": 3, "composure": 2, "intelligence": 4, "wits": 3, "resolve": 2}, "skills": {"athletics": 0, "brawl": 0, "craft": 0, "drive": 0, "firearms": 0, "larceny": 2, "melee": 1, "stealth": 2, "survival": 2, "animalken": 0, "etiquette": 0, "insight": 2, "intimidation": 0, "leadership": 0, "performance": 0, "persuasion": 3, "streetwise": 3, "subterfuge": 3, "academics": 0, "awareness": 0, "finance": 0, "investigation": 1, "medicine": 2, "occult": 0, "politics": 0, "science": 1, "technology": 0}, "specialties": [{"skill": "subterfuge", "name": "Lies"}, {"skill": "streetwise", "name": "Mafia Methods"}, {"skill": "persuasion", "name": "Seduction"}], "edges": [{"name": "MEDICAL CACHE (Asset)", "perks": ["Controlled Pharmaceuticals"], "notes": "Surgical supplies, pharmaceuticals, a contact who asks nothing"}, {"name": "CRIMINAL NETWORK (Asset)", "perks": [], "notes": "Organised crime, grey market, the underground"}], "advantages": [{"name": "Retainer", "dots": 3}, {"name": "Iron Will", "dots": 2}, {"name": "Striking Looks", "dots": 2}, {"name": "Trauma  -  sound of a light drill (Flaw)", "dots": 1}, {"name": "Nightmares  -  recalling the torture (Flaw)", "dots": 1}], "tenets": "", "creedFields": "ANCHOR\nRage against the machine"}$sheet$::jsonb,
   $sheet${"ambition": "Reveal the identity of the true Capo Famiglia of the Giovanni Crime Family, and hurt him as much as they did her.", "desire": "Spill the blood of mobsters", "health": ["", "", "", "", "", "", "", "", "", ""], "willpower": ["", "", "", "", "", "", "", "", "", ""], "despair": false, "touchstones": "FRANCESCA PASSERINI\nAdelina’s young sister. They grew\nup together, and Adelina would\nkill a thousand people for her.", "equipment": ["", "", "", "", "", "", "", "", "", "", "", "", "", ""], "notes": "Player: Maria\nHumanity 7 - Health 5 - Willpower 4\nDesperation and Danger are tracked per cell,\nnot per character.", "age": "", "dob": "", "appearance": "", "features": "", "history": "Grew up in an orphanage, recruited by the Italian secret service, trained as a spy, sent on a Mafia infiltration mission in NYC which went awry when she was captured and tortured by the goons of the Giovanni family."}$sheet$::jsonb),
  ('vivienne', 'dead-hand', 'Vivienne Okafor',
   $sheet${"name": "Vivienne Okafor", "concept": "Assistant District Attorney, New York", "creed": "Inquisitive", "cell": "Dead Hand", "drive": "Atonement", "redemption": "", "attributes": {"strength": 1, "dexterity": 2, "stamina": 2, "charisma": 3, "manipulation": 3, "composure": 2, "intelligence": 4, "wits": 3, "resolve": 2}, "skills": {"athletics": 1, "brawl": 1, "craft": 0, "drive": 0, "firearms": 1, "larceny": 0, "melee": 0, "stealth": 0, "survival": 0, "animalken": 0, "etiquette": 1, "insight": 2, "intimidation": 0, "leadership": 0, "performance": 0, "persuasion": 3, "streetwise": 2, "subterfuge": 2, "academics": 3, "awareness": 2, "finance": 0, "investigation": 3, "medicine": 0, "occult": 1, "politics": 2, "science": 0, "technology": 1}, "specialties": [{"skill": "academics", "name": "Law"}], "edges": [{"name": "GLOBAL ACCESS (Int + Technology)", "perks": ["Letter of the Law  -  can modify criminal records"], "notes": "Pulls records, filings, financial data, surveillance"}, {"name": "SENSE THE UNNATURAL", "perks": [], "notes": "While holding a focus object, detects nearby creatures"}], "advantages": [{"name": "Status  -  DA’s office and legal circles", "dots": 3}, {"name": "Contacts  -  judges, detectives, court clerks", "dots": 2}, {"name": "Resources", "dots": 2}, {"name": "Living on the Edge (Flaw)", "dots": 2}], "tenets": "Don’t let the system’s blind spots\nbecome an excuse.\n\nEvery case gets a real answer, even\nthe ones no court will hear.\n\nNever let someone else pay for what\nyou missed.\n\n(Suggested  -  confirm with the\ntable.)", "creedFields": "CREED: INQUISITIVE\nCounters threats by studying\nthem, finding the pattern,\nworking the angle.\n\nDRIVE: ATONEMENT\nShe believes she failed to stop\nsomething dangerous once,\nknowingly or not, and is trying\nto settle that debt."}$sheet$::jsonb,
   $sheet${"ambition": "Build an airtight case  -  proof enough for herself  -  against the thing that walked out of her courtroom, and make sure it never happens to anyone else.", "desire": "Get through the next case without letting the system fail someone the way it failed her.", "health": ["", "", "", "", "", "", "", "", "", ""], "willpower": ["", "", "", "", "", "", "", "", "", ""], "despair": false, "touchstones": "Open  -  still to be built out.\nCandidates: a mentor in the DA’s\noffice who does not know why she\nhas changed; a defendant she\nhelped convict while distracted\nby the real case; someone from\nthe original case still out\nthere, unaware of what almost\nhappened to them.", "equipment": ["", "", "", "", "", "", "", "", "", "", "", "", "", ""], "notes": "Best trait: Intelligence  -  the relentless,\ndetail-obsessed legal mind that missed nothing the\nsecond time around.\n\nTONE\nSharp, controlled, courtroom-composed even in\ndanger. She does not lose her cool; she redirects\nit.\n\nNOTE ON SKILLS\nThe source sheet lists Empathy 1 alongside Insight\n2. Hunter 5e renamed Empathy to Insight, so the\nhigher value is used here.", "age": "", "dob": "", "appearance": "", "features": "", "history": "Vivienne Okafor is an Assistant District Attorney in New York, seven years in, sharp enough that she has stopped being surprised when opposing counsel recognises her name before she has said it. She built her reputation on being unshakeable  -  the kind of prosecutor who does not blink, does not rattle, closes strong. Then she lost a case she should have won.\n\nThe defendant walked. Clean acquittal, no technicality, just a jury that believed a story Vivienne knew was not true. She spent months afterward picking the trial apart, convinced she had missed something in the evidence or the witness prep. What she eventually found was not a legal error. It was a pattern of details she had dismissed as irrelevant  -  because they made no rational sense  -  that only made sense once she stopped assuming the defendant was human.\n\nShe never got to retry the case; double jeopardy saw to that. What she got instead was the absolute certainty that something walked out of her courtroom that should never have been found not guilty by any court, and that certainty has not left her. She still works the DA’s office by day. At night she is trying to make sure it does not happen again  -  and quietly hunting for a way to finish what the trial could not."}$sheet$::jsonb),
  ('raven', 'dead-hand', 'Raven Reyes',
   $sheet${"name": "Raven Reyes", "concept": "Former gang survivor, now ER nurse", "creed": "Underground", "cell": "Dead Hand", "drive": "Oath", "redemption": "", "attributes": {"strength": 3, "dexterity": 2, "stamina": 2, "charisma": 3, "manipulation": 1, "composure": 4, "intelligence": 3, "wits": 2, "resolve": 2}, "skills": {"athletics": 1, "brawl": 0, "craft": 1, "drive": 2, "firearms": 2, "larceny": 0, "melee": 1, "stealth": 2, "survival": 2, "animalken": 0, "etiquette": 0, "insight": 1, "intimidation": 2, "leadership": 1, "performance": 1, "persuasion": 1, "streetwise": 1, "subterfuge": 0, "academics": 1, "awareness": 0, "finance": 0, "investigation": 1, "medicine": 1, "occult": 0, "politics": 1, "science": 0, "technology": 0}, "specialties": [], "edges": [{"name": "IMPROVISED GEAR (Aptitude)", "perks": [], "notes": "Builds something useful out of whatever is lying around"}, {"name": "LIBRARY (Asset)", "perks": ["How to Harm Them"], "notes": "Researching a creature reveals its weaknesses to the cell"}], "advantages": [{"name": "Iron Will", "dots": 2}, {"name": "Allies  -  Dr. Jacob Miller", "dots": 2}, {"name": "Danger Sense", "dots": 1}, {"name": "Contacts  -  medical and street", "dots": 1}, {"name": "Luck", "dots": 1}, {"name": "Dark Secret  -  forced into a gang (Flaw)", "dots": 1}, {"name": "Enemy  -  a former gang leader (Flaw)", "dots": 1}], "tenets": "", "creedFields": "ANCHOR\nThe emergency room: where she\nfeels she belongs, and where she\nremembers why she left her old\nlife. Every life is worth saving.\nNo one is beyond redemption."}$sheet$::jsonb,
   $sheet${"ambition": "Save more lives than the ones she destroyed, exposing the force of corruption.", "desire": "Find out the monster behind the recent attacks", "health": ["", "", "", "", "", "", "", "", "", ""], "willpower": ["", "", "", "", "", "", "", "", "", ""], "despair": false, "touchstones": "LINA, HER YOUNG SISTER\nThe only person she kept away\nfrom the gang. Her safety is a\npriority. She is kept far from\nNew York at Mr Wilson’s farm, an\nold friend of her late father.", "equipment": ["", "", "", "", "", "", "", "", "", "", "", "", "", ""], "notes": "Player: Lily\nHumanity 7 - Health 5 - Willpower 6\nDesperation and Danger are tracked per cell,\nnot per character.", "age": "", "dob": "", "appearance": "", "features": "", "history": "Former gang member forced into a life of violence. Escaped, changed her life, and became an ER nurse. Now she secretly hunts the creatures preying on New York while trying to keep her past away.\n\nIron Will: years of surviving a violent gang and later working in the ER have made her exceptionally resilient; she remains calm under fear, pain and stress.\n\nDanger Sense: her gang past makes her instinctively notice when something is wrong.\n\nContacts: doctors, nurses, paramedics and medical examiners can provide information to her; underground gang members from her past and some allies cooperate.\n\nAllies: Dr. Jacob Miller, Chief of Emergency Medicine and her mentor, can quietly access records, change schedules, cover up, and shows up whenever she needs him.\n\nLuck: she always seems to survive impossible situations."}$sheet$::jsonb)
on conflict (slug) do update set name = excluded.name, data = excluded.data, play = excluded.play, updated_at = now();
